def _integer(name, value, minimum=0):
    if isinstance(value, (bool, np.bool_)):
        raise ValueError(f"{name} must be an integer, not a boolean.")
    try:
        result = operator.index(value)
    except TypeError as exc:
        raise ValueError(f"{name} must be an integer.") from exc
    if result < minimum:
        raise ValueError(f"{name} must be >= {minimum}.")
    return result


def _set_bits(mask):
    while mask:
        bit = mask & -mask
        yield bit.bit_length() - 1
        mask ^= bit


def _repair_and_extend(mask, adjacency, weights):
    """Remove conflicts, then greedily extend to a maximal independent set."""
    while True:
        conflicting = [
            v for v in _set_bits(mask) if adjacency[v] & mask
        ]
        if not conflicting:
            break
        # Remove highly conflicting vertices; preserve high QAOA marginals.
        remove = max(
            conflicting,
            key=lambda v: (
                (adjacency[v] & mask).bit_count(),
                -float(weights[v]),
                v,
            ),
        )
        mask &= ~(1 << remove)

    available = ((1 << len(adjacency)) - 1) & ~mask
    for v in _set_bits(mask):
        available &= ~adjacency[v]

    while available:
        add = min(
            _set_bits(available),
            key=lambda v: (
                (adjacency[v] & available).bit_count(),
                -float(weights[v]),
                v,
            ),
        )
        mask |= 1 << add
        available &= ~((1 << add) | adjacency[add])
    return mask


def _exact_completion(adjacency, incumbent, target, weights):
